protection.original:
/* Data protection, privacy review, encryption, and backup surfaces */

.privacy-notice {
  padding: 10px 14px; border-radius: var(--radius-sm); font-size: 13px;
  margin-top: 12px; line-height: 1.5;
}
.privacy-notice-success {
  background: var(--green-bg); border: 1px solid color-mix(in srgb, var(--green) 25%, transparent); color: var(--green);
}
.privacy-notice-warning {
  background: var(--yellow-bg); border: 1px solid color-mix(in srgb, var(--yellow) 25%, transparent); color: var(--yellow);
}

/* PII overlay shared by the review and diff viewer. */
.pii-warning-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: rgba(0,0,0,0.82);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.2s;
  overflow: hidden;
  overscroll-behavior: contain;
  padding: 18px;
}
.pii-warning-overlay.show {
  opacity: 1;
}

/* PII Diff Viewer (debug mode) */
.pii-diff-modal {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  max-width: 95vw;
  width: 1200px;
  max-height: 85vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
  box-shadow: var(--shadow-lg);
}
.pii-diff-modal h3 {
  margin: 0 0 16px;
  font-size: 16px;
}
.pii-review-modal {
  padding: 0;
}
.pii-review-head {
  flex-shrink: 0;
  background: color-mix(in srgb, var(--bg-secondary) 96%, var(--bg-card));
}
.pii-review-intro {
  margin: 0;
  padding: 16px 24px 12px;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.5;
}
.pii-diff-viewer {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  overflow: hidden;
  flex: 1;
  font-family: monospace;
  font-size: 11px;
  line-height: 1.6;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  min-height: 0;
}
.pii-diff-left, .pii-diff-right {
  padding: 8px;
  overflow-x: auto;
  overflow-y: auto;
  overscroll-behavior: contain;
  white-space: pre;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.pii-diff-left {
  background: color-mix(in srgb, var(--red) 6%, var(--bg-secondary));
}
.pii-diff-right {
  background: color-mix(in srgb, var(--green) 5%, var(--bg-secondary));
}
.pii-edit-textarea {
  width: 100%;
  flex: 1;
  resize: none;
  border: none;
  outline: none;
  background: transparent;
  color: var(--text-primary);
  font-family: monospace;
  font-size: 11px;
  line-height: 1.6;
  white-space: pre;
  padding: 0;
  margin: 0;
}
.pii-edit-textarea[readonly] {
  opacity: 0.7;
}
.pii-stream-status {
  font-size: 12px;
  color: var(--text-muted);
  padding: 6px 0 0;
  font-family: var(--font-display);
  flex-shrink: 0;
}
.pii-stream-waiting {
  animation: pii-pulse 1.2s ease-in-out infinite;
}
.pii-stream-waiting::before {
  content: '';
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--green);
  margin-right: 6px;
  vertical-align: middle;
  animation: pii-dot-pulse 1.2s ease-in-out infinite;
}
@keyframes pii-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.4; } }
@keyframes pii-dot-pulse { 0%, 100% { transform: scale(1); } 50% { transform: scale(0.6); } }
.pii-diff-header {
  font-weight: 700;
  font-size: 12px;
  padding-bottom: 8px;
  margin-bottom: 8px;
  border-bottom: 1px solid var(--border);
  font-family: var(--font-display);
}
.pii-edit-btn {
  background: none;
  border: 1px solid var(--border);
  color: var(--accent);
  cursor: pointer;
  font-size: 11px;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  margin-left: 8px;
  transition: background 0.2s;
}
.pii-edit-btn:hover {
  background: var(--bg-card);
}
.pii-diff-highlight-removed {
  background: rgba(239,68,68,0.08);
  border-radius: 2px;
}
.pii-diff-highlight-added {
  background: rgba(34,197,94,0.08);
  border-radius: 2px;
}
.pii-word-removed {
  background: rgba(239,68,68,0.3);
  border-radius: 2px;
  padding: 0 1px;
}
.pii-word-added {
  background: rgba(34,197,94,0.3);
  border-radius: 2px;
  padding: 0 1px;
}
.pii-diff-preview {
  white-space: pre;
  flex: 1;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.pii-mobile-original {
  display: none;
}
.pii-thinking-section {
  margin-bottom: 8px;
  font-size: 12px;
}
.pii-thinking-section summary {
  cursor: pointer;
  color: var(--text-muted);
  font-family: var(--font-display);
  padding: 4px 0;
}
.pii-thinking-content {
  max-height: 120px;
  overflow-y: auto;
  padding: 8px;
  margin-top: 4px;
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--text-muted);
  white-space: pre-wrap;
  word-break: break-word;
}
.pii-search-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 24px 12px;
}
.pii-search-input {
  flex: 1;
  padding: 8px 12px;
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
}
.pii-search-input:focus {
  border-color: var(--accent);
  outline: none;
}
.pii-search-count {
  font-size: 12px;
  white-space: nowrap;
}
.pii-search-warn {
  color: var(--red);
  font-weight: 600;
}
.pii-search-clear {
  color: var(--green);
}
.pii-review-viewer {
  margin: 0 24px;
}
.pii-review-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 14px 24px;
  border-top: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 96%, var(--bg-card));
  flex-wrap: wrap;
}
.pii-review-actions [hidden] {
  display: none;
}
.pii-review-actions-simple {
  margin-top: 12px;
  padding: 0;
  border-top: 0;
  background: transparent;
}
.pii-action-spacer {
  flex: 1 1 auto;
}

@media (max-width: 768px) {
  .pii-warning-overlay {
  align-items: stretch;
  padding: 12px;
}
  .pii-diff-modal {
  width: 100%;
  max-width: none;
  height: calc(100vh - 24px);
  height: calc(100dvh - 24px);
  max-height: none;
  padding: 16px;
}
  .pii-review-modal {
  padding: 0;
}
  .pii-review-intro {
  padding: 14px 16px 10px;
}
  .pii-search-bar {
  align-items: stretch;
  flex-direction: column;
  gap: 6px;
  margin: 0 16px 10px;
}
  .pii-search-count {
  min-height: 18px;
  white-space: normal;
}
  .pii-diff-viewer {
  grid-template-columns: 1fr;
}
  .pii-review-viewer {
  margin: 0 16px;
  border: 0;
  overflow: visible;
}
  .pii-review-viewer > .pii-diff-left {
  display: none;
}
  .pii-mobile-original {
  display: block;
  margin: 0 16px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--red) 5%, var(--bg-secondary));
  color: var(--text-secondary);
  font-size: 12px;
}
  .pii-mobile-original summary {
  min-height: 40px;
  box-sizing: border-box;
  padding: 10px 12px;
  cursor: pointer;
  color: var(--text-primary);
  font-weight: 700;
}
  .pii-mobile-original-body {
  max-height: 26vh;
  overflow: auto;
  padding: 0 12px 12px;
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.55;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
  .pii-diff-right {
  min-height: 0;
  overflow: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  white-space: normal;
}
  .pii-edit-textarea,
  .pii-diff-preview {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
  .pii-review-actions {
  padding: 12px;
}
  .pii-review-actions .import-btn {
  flex: 1 1 calc(50% - 4px);
  min-height: 42px;
}
  .pii-action-spacer {
  display: none;
}
}

