genetics.original:
/* Genetics and DNA import surfaces */

/* Genetics empty-state CTA - lives in the dashboard genetics slot when
   no DNA data exists. Same compact in-context pattern as the Wearables
   "Connect a wearable" stub: subtle dashed border, no full-card weight. */
.genetics-empty-stub {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 18px;
  margin-top: 16px;
