}
.genetics-empty-stub-sub {
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.45;
}
.genetics-empty-stub-arrow {
  font-size: 16px;
  color: var(--text-muted);
  align-self: center;
  flex-shrink: 0;
}
.genetics-empty-stub:hover .genetics-empty-stub-arrow {
  color: var(--purple);
