/* DNA Import Preview */
.dna-preview-modal { width: min(90vw, 560px); max-width: 560px; max-height: 80vh; display: flex; flex-direction: column; padding: 0; overflow: hidden; }
.dna-preview-header { padding: 16px 20px 12px; border-bottom: 1px solid var(--border); }
.dna-preview-title { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
.dna-preview-stats { font-size: 12px; color: var(--text-muted); }
.dna-preview-apoe {
  margin-top: 8px;
  font-size: 13px;
  padding: 6px 10px;
  background: var(--bg-hover);
  border-radius: var(--radius-sm);
}
.dna-preview-body { flex: 1; overflow-y: auto; padding: 12px 20px; }
.dna-preview-group {
  margin-bottom: 14px;
}
.dna-preview-group-title {
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 6px;
  color: var(--text-secondary);
}
.dna-preview-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 3px 0 0;
  font-size: 12px;
}
.dna-preview-icon {
  font-size: 10px;
  flex-shrink: 0;
}
.dna-preview-gene {
  font-weight: 500;
  white-space: nowrap;
}
.dna-preview-variant {
  font-weight: 400;
  color: var(--text-muted);
}
.dna-preview-category {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-left: 4px;
}
.dna-preview-genotype {
  font-family: var(--font-mono);
  color: var(--accent);
  font-weight: 600;
  font-size: 11px;
  margin-left: auto;
}
.dna-preview-note {
  font-size: 11px;
  color: var(--text-muted);
  padding: 0 0 6px 18px;
  line-height: 1.4;
  border-bottom: 1px solid var(--border-subtle, rgba(255,255,255,0.04));
  margin-bottom: 2px;
}
.dna-preview-assessment {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  padding: 3px 0 2px 18px;
}
.dna-preview-collapsible {
  cursor: pointer;
}
.dna-preview-expand-hint {
  font-size: 10px;
  font-weight: 400;
  color: var(--text-muted);
}
.dna-preview-collapsed-items {
  display: none;
}
.dna-preview-group.expanded .dna-preview-collapsed-items {
  display: block;
}
.dna-preview-group.expanded .dna-preview-expand-hint {
  display: none;
}
.dna-preview-disclaimer { padding: 8px 20px; font-size: 11px; color: var(--text-muted); border-top: 1px solid var(--border); }
.dna-preview-actions { padding: 12px 20px; display: flex; gap: 8px; justify-content: flex-end; border-top: 1px solid var(--border); }
.dna-manual-modal {
  width: min(92vw, 640px);
  max-width: 640px;
  max-height: min(88vh, 760px);
}
.dna-manual-header {
  background: linear-gradient(135deg, color-mix(in srgb, var(--purple) 10%, transparent), transparent 60%);
}
.dna-manual-snp-body {
  display: grid;
  gap: 14px;
  background: var(--bg-secondary);
  padding-bottom: 16px;
}
.dna-manual-card {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-card);
  padding: 12px;
}
.dna-manual-card-bulk {
  background: color-mix(in srgb, var(--bg-card) 94%, var(--purple) 6%);
}
.dna-manual-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}
.dna-manual-section-head span {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}
.dna-manual-section-head small {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
  text-align: right;
}
.dna-manual-field {
  display: grid;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.dna-manual-source {
  padding: 0 2px;
  max-width: none;
}
.dna-manual-input,
.dna-manual-textarea {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.03);
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}
.dna-manual-input {
  min-height: 40px;
  padding: 9px 11px;
}
.dna-manual-textarea {
  resize: vertical;
  min-height: 104px;
  padding: 10px 11px;
  font-family: var(--font-mono);
  line-height: 1.45;
}
.dna-manual-input::placeholder,
.dna-manual-textarea::placeholder {
  color: var(--text-muted);
  opacity: 0.72;
}
.dna-manual-input:hover,
.dna-manual-textarea:hover {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
}
.dna-manual-input:focus,
.dna-manual-textarea:focus {
  outline: none;
  border-color: var(--accent);
  background: var(--bg-card);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
}
.dna-manual-help {
  margin: 0;
  padding: 4px 2px 0;
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.45;
}
@media (max-width: 560px) {
  .dna-preview-modal { max-width: min(96vw, 560px); }
  .dna-manual-section-head {
  display: grid;
}
  .dna-manual-section-head small {
  text-align: left;
}
}

/* Shared genetics detail references used by marker details and the Genome page. */
.detail-genetics { margin: 12px 0; padding: 10px 12px; background: var(--bg-hover); border-radius: var(--radius-sm); border: 1px solid var(--border); }
.detail-genetics-ref {
  color: var(--text-secondary);
  font-size: 10px;
  text-decoration: none;
  border-bottom: 1px dotted currentColor;
  margin-left: 4px;
}
.detail-genetics-ref:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}
.genetics-ai-link {
  padding: 0;
  border: 0;
  border-bottom: 1px dotted currentColor;
  background: none;
  font-family: inherit;
  cursor: pointer;
}

/* Genetics Dashboard Section */
.genetics-section {
  margin-top: 16px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 14px 16px;
}
.genetics-section .section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: space-between;
  margin-bottom: 8px;
}
.genetics-section .section-header > span:first-child {
  font-size: 14px;
  font-weight: 600;
}
.genetics-section .section-meta {
  font-size: 11px;
  color: var(--text-muted);
}
.genetics-collapse-arrow {
  display: inline-block;
  transition: transform 0.2s;
  margin-left: 4px;
}
.genetics-collapse-arrow.collapsed {
  transform: rotate(-90deg);
}
.genetics-body.hidden {
  display: none;
}
/* mtDNA Haplogroup */
