  .genetics-finding-impact {
  grid-column: 2;
  grid-row: 2;
  justify-self: start;
}
  .genetics-finding-genotype {
  grid-column: 3;
  grid-row: 1;
}
  .genetics-finding-axes {
  grid-column: 1 / -1;
}
  .genetics-finding-note {
  grid-column: 1 / -1;
  padding-left: 0;
  line-height: 1.4;
}
  .genetics-section .section-header {
  flex-wrap: wrap;
}
  .genetics-section .section-meta {
  width: 100%;
}
}

