/* Manual Entry Button & Form */
.manual-entry-btn {
  width: 100%; padding: 10px; border-radius: 6px;
  border: 1px dashed var(--border); background: transparent;
  color: var(--text-secondary); font-size: 13px; font-weight: 500;
  cursor: pointer; font-family: inherit; transition: all 0.15s;
  margin-top: 8px;
}
.manual-entry-btn:hover { border-color: var(--accent); color: var(--accent); background: rgba(79,140,255,0.05); }
.manual-entry-form {
  margin-top: 16px;
}
.manual-entry-form .me-field {
  margin-bottom: 12px;
}
.manual-entry-form .me-field label {
  display: block;
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 4px;
  font-weight: 500;
}
.manual-entry-form .me-field input {
  width: 100%;
  padding: 8px 12px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
}
.manual-entry-form .me-field input:focus {
  border-color: var(--accent);
}
.manual-entry-form .me-field textarea {
  width: 100%;
  padding: 8px 12px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
  resize: vertical;
}
.manual-entry-form .me-field textarea:focus {
  border-color: var(--accent);
}
.manual-entry-form .me-field select {
  width: 100%;
  padding: 8px 12px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
}
.manual-entry-form .me-field select:focus {
  border-color: var(--accent);
}
.manual-entry-form .me-context-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.manual-entry-form .me-context-grid .me-field {
  min-width: 0;
}
.manual-entry-form .me-field .me-optional {
  color: var(--text-muted);
  font-weight: 400;
  text-transform: none;
  letter-spacing: 0;
}
.manual-entry-form .me-field small {
  display: block;
  margin-top: 5px;
  color: var(--text-muted);
  font-size: 10px;
  line-height: 1.35;
}
.manual-entry-form .me-field select.me-unit-select {
  width: auto;
  padding: 2px 8px;
  font-size: 11px;
  margin-left: 6px;
  font-weight: 400;
  color: var(--text-muted);
  vertical-align: middle;
}
.manual-entry-form .me-context {
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: 16px;
  padding: 10px;
  background: var(--bg-card);
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
}
@media (max-width: 520px) {
  .manual-entry-form .me-context-grid {
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
}
}

/* Note icon in detail modal */
.mv-note {
  display: inline-flex; align-items: center; justify-content: center;
  margin-left: 6px; padding: 1px 5px;
  border: 1px solid var(--border); border-radius: 999px;
  background: transparent; color: var(--text-muted);
  font-family: var(--font-mono); font-size: 9px; font-weight: 700;
  text-transform: uppercase; cursor: pointer;
}
.mv-note:hover { border-color: var(--accent); color: var(--accent); }
.mv-note-text {
  display: none; font-size: 11px; color: var(--yellow);
  margin-top: 6px; padding: 6px 8px; line-height: 1.4;
  background: var(--yellow-bg); border-radius: 4px;
  text-align: left; word-break: break-word;
}
.mv-note-text.show { display: block; }

/* Marker Notes in Detail Modal */
.marker-detail-modal .marker-note-section {
  margin: 12px 0;
  padding: 10px 12px;
  background: var(--bg-hover);
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
}
.marker-detail-modal .marker-note-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.marker-detail-modal .marker-note-label {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-secondary);
}
.marker-detail-modal .marker-note-edit-btn {
  background: none;
  border: none;
  color: var(--accent);
  font-size: 11px;
  cursor: pointer;
  font-family: inherit;
  padding: 0;
}
.marker-detail-modal .marker-note-edit-btn:hover {
  text-decoration: underline;
}
.marker-detail-modal .marker-note-text {
  font-size: 13px;
  color: var(--text-primary);
  margin-top: 6px;
  line-height: 1.5;
  white-space: pre-line;
}
.marker-detail-modal .marker-note-editor {
  margin-top: 8px;
}
.marker-detail-modal .marker-note-editor textarea {
  width: 100%;
  background: var(--bg-primary);
  color: var(--text-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 8px;
  font-size: 13px;
  font-family: inherit;
  resize: vertical;
}
.marker-detail-modal .marker-note-editor textarea:focus {
  outline: none;
  border-color: var(--accent);
}
.marker-detail-modal .marker-note-actions {
  display: flex;
  gap: 6px;
  margin-top: 6px;
}

/* Calculated marker missing inputs */
.calc-missing-inputs {
  color: var(--text-muted);
  font-size: 0.8rem;
  text-align: center;
  margin-top: 12px;
  padding: 8px 12px;
  border-radius: 6px;
  background: var(--bg-secondary);
  border: 1px dashed var(--border);
}
/* Ask AI Button in Marker Detail Modal */
.ask-ai-btn {
  width: 100%; padding: 10px; border-radius: 6px;
  border: 1px solid var(--accent); background: transparent;
  color: var(--accent); font-size: 13px; font-weight: 500;
  cursor: pointer; font-family: inherit; transition: all 0.2s;
  margin-top: 16px;
}
.ask-ai-btn:hover { background: var(--accent-gradient); color: white; border-color: transparent; box-shadow: 0 2px 12px rgba(79, 140, 255, 0.2); }

@media (max-width: 480px) {
  .modal.marker-detail-modal {
  padding: 0;
}
}
@media (max-width: 375px) {
  .modal.marker-detail-modal {
  padding: 0;
  max-width: calc(100vw - 16px);
}
}
@media (hover: none) {
  .marker-detail-modal .mv-delete {
  opacity: 0.7;
}
  .marker-detail-modal .modal-value-card .mv-source {
  opacity: 0.7;
  max-height: 1.2em;
  margin-bottom: 2px;
}
}

/* Fixed Custom Marker presentation; new-category display remains controller-owned. */
.marker-form-modal #cm-new-cat-row {
  margin-top: 6px;
  gap: 8px;
  align-items: center;
}
.marker-form-modal #cm-new-cat-icon {
  cursor: pointer;
  font-size: 20px;
  min-width: 28px;
  text-align: center;
}
.marker-form-modal #cm-new-cat {
  flex: 1;
}
.marker-form-modal .cm-range-row {
  display: flex;
  gap: 8px;
}
.marker-form-modal .cm-range-divider {
  line-height: 36px;
}

