recommendations.original:
/* Recommendation sections */
.rec-tier-hint:not(:where([data-tips-view], [data-tips-view] *)) { font-weight: 400; text-transform: none; letter-spacing: 0; opacity: 0.7; font-style: italic; }
.rec-product-link:not(:where([data-tips-view], [data-tips-view] *)) { color: var(--accent); text-decoration: none; font-size: 12px; white-space: nowrap; padding: 6px 12px; }
.rec-product-link:not(:where([data-tips-view], [data-tips-view] *)):hover { text-decoration: underline; }
.rec-mini-disclaimer:not(:where([data-tips-view], [data-tips-view] *)) { font-size: 9px; color: var(--text-muted); margin-top: 8px; }
.rec-chat-wrapper:not([data-chat-recommendations-view]) { margin-top: 8px; border-top: 1px solid var(--border); padding-top: 8px; }
.rec-chat-summary:not(:where([data-chat-recommendations-view] *)) {
  font-size: 13px; font-weight: 600; color: var(--accent); cursor: pointer;
  list-style: none; padding: 7px 9px;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--border)); border-radius: 8px;
  background: color-mix(in srgb, var(--accent) 5%, transparent);
  transition: color 0.15s, border-color 0.15s, background 0.15s, box-shadow 0.15s;
}
.rec-chat-summary:not(:where([data-chat-recommendations-view] *))::-webkit-details-marker { display: none; }
.rec-chat-summary:not(:where([data-chat-recommendations-view] *))::marker { display: none; content: ''; }
.rec-chat-summary:not(:where([data-chat-recommendations-view] *))::before { content: '\25B8'; margin-right: 6px; display: inline-block; transition: transform 0.2s; font-size: 11px; }
.rec-chat-wrapper:not([data-chat-recommendations-view])[open] > .rec-chat-summary:not(:where([data-chat-recommendations-view] *))::before { transform: rotate(90deg); }
.rec-chat-summary:not(:where([data-chat-recommendations-view] *)):hover {
  color: var(--accent); border-color: color-mix(in srgb, var(--accent) 48%, var(--border));
  background: color-mix(in srgb, var(--accent) 9%, transparent);
}
.rec-chat-wrapper:not([data-chat-recommendations-view])[open] > .rec-chat-summary:not(:where([data-chat-recommendations-view] *)) {
  color: var(--accent); border-color: color-mix(in srgb, var(--accent) 38%, var(--border));
  background: color-mix(in srgb, var(--accent) 7%, transparent);
}
.rec-chat-count:not(:where([data-chat-recommendations-view] *)) { color: inherit; font-weight: 650; }
.rec-chat-wrapper:not([data-chat-recommendations-view]).rec-chat-unseen > .rec-chat-summary:not(:where([data-chat-recommendations-view] *)) {
  color: var(--accent); border-color: color-mix(in srgb, var(--accent) 52%, var(--border));
  background: color-mix(in srgb, var(--accent) 11%, transparent);
}
.rec-chat-wrapper:not([data-chat-recommendations-view]).rec-chat-attention > .rec-chat-summary:not(:where([data-chat-recommendations-view] *)) {
  animation: recChatAttention 1s ease-in-out 3;
}
@keyframes recChatAttention {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--accent) 0%, transparent); }
  50% { box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent) 20%, transparent); }
}
.rec-chat-new:not(:where([data-chat-recommendations-view] *)) {
  display: inline-flex; align-items: center; margin-left: 8px; padding: 1px 6px;
  border-radius: 999px; background: color-mix(in srgb, var(--accent) 14%, transparent);
  color: var(--accent); font-size: 9px; font-weight: 700; letter-spacing: 0.04em;
  text-transform: uppercase; vertical-align: 1px;
}
@media (prefers-reduced-motion: reduce) {
  .rec-chat-wrapper.rec-chat-attention > .rec-chat-summary { animation: none; }
}
.rec-dna-evidence:not(:where([data-tips-view], [data-tips-view] *)) { display: inline-flex; margin-left: 4px; padding: 1px 5px; border: 1px solid var(--border); border-radius: 999px; color: var(--text-muted); font-size: 9px; font-weight: 700; white-space: nowrap; }

